  keepAliveTimeout: 10000, // Close sockets before remote 15s keep-alive closes them
  connections: 100         // Allow up to 100 concurrent sockets
});
setGlobalDispatcher(customAgent);

async function runLoadTest() {
  const shopifyUrl = 'https://some-shop-id.myshopify.com/admin/api/2024-04/graphql.json';

  // Make 100 concurrent POST requests
  const requests = Array.from({ length: 100 }).map(async (_, index) => {
    try {
      const response = await fetch(shopifyUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Shopify-Access-Token': 'shpat_mock_token_goes_here'
        },
        body: JSON.stringify({ query: '{ shop { name } }' })
      });
      await response.text();
      console.log(`Request #${index} succeeded`);
    } catch (err) {
      console.error(`Request #${index} failed:`, err);
    }
  });

  await Promise.all(requests);
}

runLoadTest();
```

